#[test]
fn blue_containment_full_on_representatives() {
    // 蓝：标准口径下证据 100% 保留且产生真实压减（与 Python 工具侧 70/70 一致）。
    let cases = [BUILD_01, STACK_01, DIFF_01, LOG_01, TEST_01];
    for c in &cases {
        let r = run(c, &cfg());
        assert_eq!(
            r.evidence_kept, r.evidence_total,
            "{} 证据未全保留: {:?}",
            c.id, r.miss
        );
        assert!(r.cut_pct > 0.0, "{} 必须产生真实压减", c.id);
        assert_eq!(r.mode, Mode::Sieve, "{} 应走 sieve 路径", c.id);
    }
}

#[test]
fn red_guard_evidence_never_lost_under_hard_cap() {
    // 红：守卫断言——--max-tokens 极紧时证据地板最高优先，证据恒保留且
    // 如实报告 overflow（绝不静默丢弃）。针尖模式（context=0）只保留 query
    // 锚定的种子行、注解块行可省略，是设计语义而非缺陷，不在本守卫内。
    for c in &[BUILD_01, DIFF_01, LOG_01] {
        let hard = Config {
            max_tokens: Some(1),
            ..cfg()
        };
        let r = run(c, &hard);
        assert_eq!(
            r.evidence_kept, r.evidence_total,
            "{} --max-tokens 挤掉了证据: {:?}",
            c.id, r.miss
        );
        assert!(
            matches!(r.mode, Mode::OverflowEvidence | Mode::OverflowFill),
            "{} 极紧上限应如实报告 overflow，got {:?}",
            c.id,
            r.mode
        );
    }
}

#[test]
fn amber_failopen_keeps_all_evidence() {
    // 黄：无信号切片 fail-open 原样返回 → 证据自然全保留（只删不改不变量）。
    let no_sig = Slice {
        id: "failopen-probe",
        query: "zzzznonexistentword",
        full_text: LOG_01.full_text,
        evidence: LOG_01.evidence,
    };
    let r = run(&no_sig, &cfg());
    assert_eq!(r.mode, Mode::FailOpenZeroSignal);
    assert_eq!(r.evidence_kept, r.evidence_total);
    assert_eq!(r.kept, r.total, "failopen 原样保留");
    assert_eq!(r.chars_in, r.chars_out);
}

#[test]
fn amber_summarize_matches_per_slice() {
    // 黄：汇总计数必须与逐切片判定一致（协议自洽）。
    let reports: Vec<Report> = [BUILD_01, TEST_01].iter().map(|c| run(c, &cfg())).collect();
    let s: Summary = summarize(&reports);
    assert_eq!(s.slices, 2);
    assert_eq!(s.evidence_kept, s.evidence_total);
    assert!(s.mean_cut_pct > 0.0, "平均压减应为正");
    assert!(s.miss.is_empty());
}
